-- MySQL 5.1 compatible. Run once on wangchu database. UTC epoch ms; display as Asia/Seoul.
CREATE TABLE IF NOT EXISTS minigame_sessions (id CHAR(36) CHARACTER SET ascii NOT NULL,user_id BIGINT NOT NULL,game VARCHAR(16) CHARACTER SET ascii NOT NULL,rule_version INT NOT NULL,seed BIGINT UNSIGNED NOT NULL,mode VARCHAR(16) CHARACTER SET ascii NOT NULL DEFAULT 'free',bet_amount BIGINT NOT NULL DEFAULT 0,payout_amount BIGINT NOT NULL DEFAULT 0,status VARCHAR(16) CHARACTER SET ascii NOT NULL DEFAULT 'running',metric INT NOT NULL DEFAULT 0,elapsed_ms INT NOT NULL DEFAULT 0,action_count INT NOT NULL DEFAULT 0,started_at BIGINT NOT NULL,ended_at BIGINT NULL,created_at BIGINT NOT NULL,expires_at BIGINT NOT NULL,eligible TINYINT NOT NULL DEFAULT 0,validation_reason VARCHAR(255) NOT NULL DEFAULT '',replay MEDIUMTEXT NULL,PRIMARY KEY(id),KEY mg_user_started(user_id,started_at),KEY mg_game_user_result(game,user_id,status,eligible,metric),KEY mg_started(started_at),KEY mg_status_started(status,started_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS minigame_best (game VARCHAR(16) CHARACTER SET ascii NOT NULL,user_id BIGINT NOT NULL,session_id CHAR(36) CHARACTER SET ascii NOT NULL,metric INT NOT NULL,achieved_at BIGINT NOT NULL,PRIMARY KEY(game,user_id),KEY mg_ranking(game,metric,achieved_at,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS minigame_audit (id BIGINT NOT NULL AUTO_INCREMENT,session_id CHAR(36) CHARACTER SET ascii NOT NULL,admin_id BIGINT NOT NULL,action VARCHAR(16) CHARACTER SET ascii NOT NULL,reason VARCHAR(255) NOT NULL,created_at BIGINT NOT NULL,PRIMARY KEY(id),KEY mg_audit_session(session_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8;
